"""Demo: ground-state degeneracy law GSD(A,g)=d^g and its structural identities."""
from __future__ import annotations


def gsd(d: int, g: int) -> int:
    """GSD(A, g) = d^g, with d = |A| the number of anyon types."""
    return d ** g


def main() -> None:
    for d in (2, 3, 4):
        print(f"d={d}:", [gsd(d, g) for g in range(5)])
    # handle recursion, connected sum, torus value
    assert all(gsd(d, g + 1) == d * gsd(d, g) for d in (2, 3, 4) for g in range(6))
    assert all(gsd(d, g + h) == gsd(d, g) * gsd(d, h)
               for d in (2, 3, 4) for g in range(4) for h in range(4))
    assert all(gsd(d, 1) == d for d in (2, 3, 4, 5))
    print("All degeneracy identities verified.")


if __name__ == "__main__":
    main()

"""Demo: cyclic anyons Z_n -> unitary discrete Fourier S-matrix."""
from __future__ import annotations

import cmath
import math
from typing import List


def cyclic_smatrix(n: int) -> List[List[complex]]:
    """S_{a,b} = (1/sqrt n) exp(2 pi i a b / n): the discrete Fourier matrix."""
    norm = 1.0 / math.sqrt(n)
    return [[norm * cmath.exp(2j * math.pi * (a * b % n) / n)
             for b in range(n)] for a in range(n)]


def is_unitary(S: List[List[complex]], tol: float = 1e-9) -> bool:
    """Check sum_c S_{a,c} conj(S_{b,c}) = delta_{a,b}."""
    d = len(S)
    return all(abs(sum(S[a][c] * S[b][c].conjugate() for c in range(d))
                   - (1.0 if a == b else 0.0)) < tol
               for a in range(d) for b in range(d))


def main() -> None:
    for n in (2, 3, 4, 5, 6):
        print(f"n={n}: unitary = {is_unitary(cyclic_smatrix(n))}")


if __name__ == "__main__":
    main()

